 try{stream.holdPresentation();port.onmessage({data:{kind:'publication',session:'s',publication:{session:'s',sequence:1,snapshot:serializeConfirmedState(next),events:[event],physicsPose:null}}});assert.equal(state.elapsed,old);assert.equal(clock.elapsed,old);assert.deepEqual(order,[]);stream.releasePresentation();assert.deepEqual(order,['physics','event','terrain','motion','confirmed','ack']);}finally{stop();stream.dispose();clock.dispose();}
