test('deferred work checkpoint resumes across the live channel without losing ordered events',async()=>{
 const state=fixture(),authority=deserialize(serialize(state)),journal=createPresentationRecoveryJournal({capacity:8,highWatermark:2}),events=[],bases=[],errors=[];let terrainReady=false;
 const post=(target,message)=>queueMicrotask(()=>target.onmessage?.({data:structuredClone(message)})),senderPort={postMessage:m=>post(receiverPort,m),start(){},close(){}},receiverPort={postMessage:m=>post(senderPort,m),start(){},close(){}};
 const sender=openVisualStream(senderPort,'s',()=>{},{workRecovery:true,recoveryJournal:journal,onCheckpointAcknowledged:base=>bases.push(base)}),receiver=createConfirmedPresentationStream({port:receiverPort,session:'s',state,terrain:{confirm(){}},onConfirmed:message=>events.push(...message.events.map(event=>event.type)),onError:error=>errors.push(error),prepareWorkCheckpoint:message=>{if(!terrainReady){const error=Error('pending terrain');error.code='work-checkpoint-terrain-pending';throw error;}return {version:1,sequence:message.sequence,effects:[]};}});
 const flush=()=>new Promise(resolve=>setTimeout(resolve,0)),packet=(sequence,checkpoint=false)=>{if(sequence>1)emit(authority,'NightStarted');return {session:'s',sequence,snapshot:serializeConfirmedState(authority),events:sequence===1?[]:[authority.events.at(-1)],physicsPose:null,...(checkpoint?{terrainCheckpoint:{sequence,chunks:[]}}:{})};};
 try{sender.publish(packet(1,true),true);await flush();assert.equal(journal.status().checkpointDeferred,true);assert.equal(journal.status().base,null);sender.publish(packet(2),true);await flush();sender.publish(packet(3),true);await flush();assert.deepEqual(events,['NightStarted','NightStarted']);assert.equal(journal.status().entries,0);assert.equal(sender.blocked(),false);terrainReady=true;assert.equal(receiver.workCheckpointReady(),true);await flush();assert.equal(journal.status().checkpointRetry,true);assert.equal(sender.blocked(),false);sender.publish(packet(4,true),true);await flush();assert.equal(journal.status().base,4);assert.deepEqual(bases.map(base=>base.sequence),[4]);assert.deepEqual(events,['NightStarted','NightStarted','NightStarted']);assert.deepEqual(errors,[]);}finally{receiver.dispose();sender.close();journal.dispose();}
});

